# Auto-generate description_text for each material
for m in materials:
    cn = m["common_name"]
    cls = m["material_class"].replace("_", " ")
    ys = m["yield_strength_MPa"]
    cs = m["corrosion_seawater"]
    cs_label = ["", "poor", "fair", "moderate", "good", "excellent"][cs]
    wld = m["weldability"]
    wld_label = ["", "poor", "fair", "moderate", "good", "excellent"][wld]
    apps = m["typical_applications"]
    warns = m["key_warnings"]
    m["description_text"] = (
        f"{cn} is a {cls} with a yield strength of {ys} MPa. "
        f"Corrosion resistance in seawater is {cs_label} ({cs}/5), "
        f"and weldability is {wld_label} ({wld}/5). "
        f"Typical applications include: {apps} "
        f"Key engineering considerations: {warns}"
    )

materials_columns = ["material_id", "common_name", "uns_number", "aisi_grade", "material_class", "condition", "yield_strength_MPa", "ultimate_tensile_strength_MPa", "elongation_percent", "hardness_HB", "fatigue_limit_MPa", "elastic_modulus_GPa", "density_kg_m3", "max_service_temp_C", "min_service_temp_C", "corrosion_seawater", "corrosion_acidic", "corrosion_alkaline", "corrosion_atmospheric", "corrosion_high_temp", "weldability", "weldability_notes", "machinability_index", "cost_class", "approx_cost_usd_per_kg", "availability", "stock_forms", "fatigue_rating", "typical_applications", "key_warnings", "sources", "description_text", "stress_table_id"]

Path("data").mkdir(exist_ok=True)

with open("data/materials.csv", "w", newline="", encoding="utf-8") as f:
    writer = csv.DictWriter(f, fieldnames=materials_columns)
    writer.writeheader()
    for mat in materials:
        writer.writerow(mat)
print(f"Wrote data/materials.csv with {len(materials)} rows")

stress_columns = ["material_id", "stress_table_id", "temperature_C", "stress_MPa", "source", "notes"]
with open("data/stress_temperature.csv", "w", newline="", encoding="utf-8") as f:
    writer = csv.DictWriter(f, fieldnames=stress_columns)
    writer.writeheader()
    total_rows = 0
    for mat_id, data in stress_data.items():
        for temp, stress in data["values"]:
            writer.writerow({"material_id": mat_id, "stress_table_id": data["stress_table_id"], "temperature_C": temp, "stress_MPa": stress, "source": data["source"], "notes": ""})
            total_rows += 1
print(f"Wrote data/stress_temperature.csv with {total_rows} rows")

print(f"\nReady. Now run: python load_v1_data.py")